agent.registerScheduleTrigger("Daily 13:25 runlist creation for TC-1", {
    timezone: "Asia/Kolkata",
    scheduleKind: "recurring",
    oneTime: null,
    recurring: {
        dayScope: "every-day",
        includedDays: [],
        windowStartTime: "13:25",
        windowEndTime: "13:25",
        intervalValue: 1,
        intervalUnit: "hours"
    }
}, async (context) => {
    const __agentHandlerResult = await (async () => {
        const scopeConversationId = "";
        const scopeLatestUserMessage = "Create a new runlist asset containing only the test-case TC-1 'New test case'.";
        const scopeSelectedOptionText = "";
        const scopeInteractiveBrowserAvailable = false;
        const scopeRequestedBrowserHostId = undefined;
        const scopeRequestedClientUserId = undefined;
        const scopeRequestedClientHomeAccountId = undefined;
        const scopeCurrentUserId = "57";
        const scopeTeamId = "6007";
        const scopeOwnerAssetId = "18296";
        const scopeActiveAssetId = "18296";
        const scopeActiveAssetType = "agent";
        const scopeActiveAssetDisplayId = "AG-1";
        const scopeActiveAssetName = "New agent";
        const scopeCurrentTeamAssetId = "16348";
        const scopeCurrentFolderAssetId = undefined;
        const scopeDefaultCreateParentAssetId = "16348";
        const scopeResolvedBlueprintGeneratorAssetId = "24858";
        const scopeResolvedKnowledgeBaseAssetId = "18261";

        const uiIntents = [];

        // 1. Resolve 'TC-1' (New test case)
        const tcSearch = await context.assets.search({
            filter: {
                teamId: scopeTeamId,
                types: ["test-case"],
                names: ["New test case"]
            }
        });

        const tc = tcSearch.items.find(item => item.displayId === "TC-1");
        if (!tc) {
            throw new Error("Could not find test case 'TC-1'.");
        }

        // 2. Create the new runlist 'New runlist'
        const newRunlist = await context.assets.create({
            type: "runlist",
            name: "New runlist",
            parentAssetId: scopeDefaultCreateParentAssetId
        });

        // 3. Add the test case to the new runlist
        // Ensure it's in manual mode for adding test cases
        await context.assets.runlists.selection.setMode(newRunlist.id, "manual");
        await context.assets.runlists.selection.addTestCases(newRunlist.id, [tc.id]);

        uiIntents.push({
            kind: "asset.open",
            target: { kind: "asset-id", assetId: newRunlist.id },
            focus: true
        });

        return {
            summary: "Successfully created the new runlist `New runlist` and populated it with `TC-1` ('New test case').",
            uiIntents
        };
    })();
    if (__agentHandlerResult && typeof __agentHandlerResult === "object" && "summary" in __agentHandlerResult) {
        console.log("[agent.handler]", String((__agentHandlerResult as { summary?: unknown }).summary ?? ""));
    }
});
